import { test } from "node:test";
import assert from "node:assert/strict";
import { makeSendHandler, type Account } from "../src/sms/api.ts";
import { countSegments } from "../src/sms/segments.ts";

function setup() {
    let now = Date.parse("2026-11-19T09:00:00Z");
    const clock = { now: () => now };
    const sent: { accountId: string; segments: number }[] = [];
    const outbox = {
        async enqueue(accountId: string, _to: string, _text: string, segments: number) {
            sent.push({ accountId, segments });
            return `msg_${sent.length}`;
        },
    };
    const accounts = new Map<string, Account>([
        ["key_trial", { id: "acme", plan: "trial" }],
        ["key_trial_2", { id: "globex", plan: "trial" }],
        ["key_std", { id: "initech", plan: "standard" }],
    ]);
    const send = makeSendHandler(accounts, outbox, clock);
    const sms = (apiKey: string, text = "Your code is 4821") => send({ apiKey, body: { to: "+14155550100", text } });
    return { sms, sent, send, advance: (ms: number) => void (now += ms) };
}

test("a trial account can send its burst, then gets 429", async () => {
    const { sms } = setup();
    for (let i = 0; i < 5; i++) assert.equal((await sms("key_trial")).status, 202);
    const limited = await sms("key_trial");
    assert.equal(limited.status, 429);
    assert.equal(limited.headers["Retry-After"], "1");
});

test("after a 429, waiting the advertised Retry-After lets the next message through", async () => {
    const { sms, advance } = setup();
    for (let i = 0; i < 5; i++) await sms("key_trial");
    const limited = await sms("key_trial");
    advance(Number(limited.headers["Retry-After"]) * 1000);
    assert.equal((await sms("key_trial")).status, 202);
});

test("a client that hammered the API recovers once it slows to its plan's rate", async () => {
    const { sms, advance } = setup();
    for (let i = 0; i < 20; i++) await sms("key_trial");
    const statuses: number[] = [];
    for (let i = 0; i < 5; i++) {
        advance(1000);
        const res = await sms("key_trial");
        statuses.push(res.status);
        if (res.status === 429) console.log(`${i + 1}s after the burst: 429 with Retry-After ${res.headers["Retry-After"]}s`);
    }
    assert.deepEqual(statuses, [202, 202, 202, 202, 202]);
});

test("Retry-After doesn't grow while a client keeps retrying", async () => {
    const { sms } = setup();
    for (let i = 0; i < 5; i++) await sms("key_trial");
    const retryAfter: string[] = [];
    for (let i = 0; i < 4; i++) retryAfter.push((await sms("key_trial")).headers["Retry-After"]);
    assert.deepEqual(retryAfter, ["1", "1", "1", "1"]);
});

test("long messages use one token per segment", async () => {
    const { sms, sent } = setup();
    assert.equal(countSegments("a".repeat(160)), 1);
    assert.equal(countSegments("a".repeat(161)), 2);
    assert.equal(countSegments("Привет ".repeat(12)), 2);
    const res = await sms("key_std", "x".repeat(400));
    assert.equal(res.status, 202);
    assert.deepEqual(res.body, { id: "msg_1", segments: 3 });
    assert.equal(res.headers["X-RateLimit-Remaining"], "27");
    assert.deepEqual(sent, [{ accountId: "initech", segments: 3 }]);
});

test("a long message that doesn't fit is refused without blocking a short one", async () => {
    const { sms, sent } = setup();
    for (let i = 0; i < 3; i++) await sms("key_trial");
    assert.equal((await sms("key_trial", "y".repeat(400))).status, 429);
    assert.equal((await sms("key_trial")).status, 202);
    assert.equal(sent.length, 4);
});

test("accounts have separate limits, and bad requests are rejected before counting", async () => {
    const { sms, send } = setup();
    for (let i = 0; i < 5; i++) await sms("key_trial");
    assert.equal((await sms("key_trial")).status, 429);
    assert.equal((await sms("key_trial_2")).status, 202);
    assert.equal((await sms("nope")).status, 401);
    assert.equal((await send({ apiKey: "key_trial_2", body: { to: "555-0100", text: "hi" } })).status, 400);
    assert.equal((await sms("key_trial_2", "z".repeat(2000))).status, 400);
    assert.equal((await sms("key_trial_2")).headers["X-RateLimit-Remaining"], "3");
});
